import java.util.*;
import java.io.*;

public class Main {
    static final int MAX = 505;
    static int n, m, mod;
    static int[] fact = new int[MAX * 4];
    static int[] inv_fact = new int[MAX * 4];
    static List<Integer> polyF = new ArrayList<>();
    static List<Integer> gPoly = new ArrayList<>();

    static int mod_value(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void add_mod(int[] x, int y) {
        x[0] = mod_value(x[0] + y);
    }

    static int bin_pow(int base, int exp) {
        int res = 1;
        while (exp != 0) {
            if ((exp & 1) != 0) res = (int) ((long) res * base % mod);
            base = (int) ((long) base * base % mod);
            exp >>= 1;
        }
        return res;
    }

    static void precompute(int n) {
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % mod);
        }
        inv_fact[n] = bin_pow(fact[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_fact[i] = (int) ((long) inv_fact[i + 1] * (i + 1) % mod);
        }
    }

    static int choose(int n, int m) {
        if (n < 0 || m < 0 || n < m) return 0;
        return (int) ((long) fact[n] * inv_fact[n - m] % mod * inv_fact[m] % mod);
    }

    static int sumSeries(int x) {
        return x * (x + 1) / 2;
    }

    static List<Integer> multiplyPoly(List<Integer> A, List<Integer> B) {
        int sizeA = A.size();
        int sizeB = B.size();
        List<Integer> C = new ArrayList<>(Collections.nCopies(sizeA + sizeB - 1, 0));
        for (int i = 0; i < sizeA; i++) {
            for (int j = 0; j < sizeB; j++) {
                int val = (int) ((long) A.get(i) * B.get(j) % mod);
                C.set(i + j, mod_value(C.get(i + j) + val));
            }
        }
        return C;
    }

    static int G(int n, int m) {
        return choose(m + n - 1, n - 1);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        m = Integer.parseInt(st.nextToken());
        n = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        precompute(m << 1);

        polyF = new ArrayList<>(Collections.nCopies(n + 1, 0));
        gPoly = new ArrayList<>(Collections.nCopies(n + 1, 0));

        polyF.set(0, 1);
        for (int i = 1; i <= n; i++) {
            int val = 0;
            for (int j = 0; j <= i - 1; j++) {
                int term = (int) ((long) polyF.get(j) * polyF.get(i - 1 - j) % mod);
                term = (int) ((long) term * choose(i - 1, j) % mod);
                add_mod(new int[]{val}, term);
            }
            val = (int) ((long) val * (i + 1) % mod);
            polyF.set(i, val);
        }

        for (int i = 1; i <= n; i++) {
            int gVal = 0;
            for (int j = 0; j <= i - 1; j++) {
                int term1 = (2L * polyF.get(j) * gPoly.get(i - 1 - j) % mod);
                term1 = (int) (term1 * choose(i - 1, j) % mod);
                term1 = (int) (term1 * (i + 1) % mod);

                int term2 = (int) ((long) choose(i - 1, j) * (sumSeries(j) + sumSeries(i - 1 - j)) % mod);
                term2 = (int) ((long) term2 * polyF.get(j) % mod);
                term2 = (int) ((long) term2 * polyF.get(i - 1 - j) % mod);

                add_mod(new int[]{gVal}, (int) ((term1 + term2) % mod));
            }
            gPoly.set(i, gVal);
        }

        polyF.set(0, 0);
        for (int i = 0; i <= n; i++) {
            gPoly.set(i, (int) ((long) gPoly.get(i) * inv_fact[i] % mod));
            polyF.set(i, (int) ((long) polyF.get(i) * inv_fact[i] % mod));
        }

        int total = 0;
        for (int i = 1; i <= m - n + 1; i++) {
            int term = (int) ((long) gPoly.get(n) * G(i + 1, m - i) % mod);
            term = (int) ((long) term * fact[n] % mod);
            term = (int) ((long) term * i % mod);
            add_mod(new int[]{total}, term);
            gPoly = multiplyPoly(gPoly, polyF);
            gPoly = gPoly.subList(0, n + 1);
        }

        System.out.println(total);
    }
}
